## State

[Redux Toolkit](https://redux-toolkit.js.org/) example slice at `src/store/counterSlice.js`, combined into the store at `src/store/store.js` (demoed by `src/components/CounterDemo.jsx`). Add your own state as a new slice, one `createSlice()` call per feature, added as one more key to the store's `reducer` map:

```js
// src/store/userPrefsSlice.js
import { createSlice } from "@reduxjs/toolkit";

const userPrefsSlice = createSlice({
  name: "userPrefs",
  initialState: { theme: "light" },
  reducers: {
    setTheme: (state, action) => {
      state.theme = action.payload;
    },
  },
});

export const { setTheme } = userPrefsSlice.actions;
export default userPrefsSlice.reducer;
```

```js
// src/store/store.js
import userPrefsReducer from "@/store/userPrefsSlice";

export const store = configureStore({
  reducer: {
    counter: counterReducer,
    userPrefs: userPrefsReducer,
  },
});
```

```jsx
import { useDispatch, useSelector } from "react-redux";
import { setTheme } from "@/store/userPrefsSlice";

const theme = useSelector((state) => state.userPrefs.theme);
const dispatch = useDispatch();
dispatch(setTheme("dark"));
```

`<Provider store={store}>` is already wired up in `src/App.jsx`, wrapping the whole tree.

