## State

[Redux Toolkit](https://redux-toolkit.js.org/) example slice at `src/store/counterSlice.ts`, combined into the store at `src/store/store.ts` (demoed by `src/components/CounterDemo.tsx`). Add your own state as a new slice, one `createSlice()` call per feature, added as one more key to the store's `reducer` map:

```ts
// src/store/userPrefsSlice.ts
import { createSlice, type PayloadAction } from "@reduxjs/toolkit";

interface UserPrefsState {
  theme: "light" | "dark";
}

const userPrefsSlice = createSlice({
  name: "userPrefs",
  initialState: { theme: "light" } as UserPrefsState,
  reducers: {
    setTheme: (state, action: PayloadAction<"light" | "dark">) => {
      state.theme = action.payload;
    },
  },
});

export const { setTheme } = userPrefsSlice.actions;
export default userPrefsSlice.reducer;
```

```ts
// src/store/store.ts
import userPrefsReducer from "@/store/userPrefsSlice";

export const store = configureStore({
  reducer: {
    counter: counterReducer,
    userPrefs: userPrefsReducer,
  },
});
```

```tsx
import { useDispatch, useSelector } from "react-redux";
import { setTheme } from "@/store/userPrefsSlice";
import type { RootState, AppDispatch } from "@/store/store";

const theme = useSelector((state: RootState) => state.userPrefs.theme);
const dispatch = useDispatch<AppDispatch>();
dispatch(setTheme("dark"));
```

`<Provider store={store}>` is already wired up in `src/App.tsx`, wrapping the whole tree. `RootState`/`AppDispatch` (exported from `src/store/store.ts`) are the types to reach for whenever you need `useSelector`/`useDispatch` typed against your store.
